import { createContext, useContext } from 'react';

const SnippetsContext = createContext([]);

/**
 * Provide the array generated by `create-snippets.js` (shape:
 * [{ name, text }]) once near the root of your app:
 *   <SnippetsProvider snippets={snippets}>
 *     <App />
 *   </SnippetsProvider>
 */
export function SnippetsProvider({ snippets = [], children }) {
  return (
    <SnippetsContext.Provider value={snippets}>
      {children}
    </SnippetsContext.Provider>
  );
}

export function useSnippet(name) {
  const snippets = useContext(SnippetsContext);
  return snippets.find((s) => s.name === name)?.text || '';
}
